package site.hsu.hub.application.adapter.out.persistence;import jakarta.persistence.*;
@Entity@Table(name="resume_submissions")public class ResumeSubmissionEntity{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="application_id",nullable=false,unique=true)private Long applicationId;@Column(name="question_id",nullable=false)private Long questionId;@Column(name="file_asset_id")private Long fileAssetId;@Column(name="external_url",length=2048)private String externalUrl;protected ResumeSubmissionEntity(){}public ResumeSubmissionEntity(Long app,Long q,Long file,String url){applicationId=app;questionId=q;fileAssetId=file;externalUrl=url;}public Long questionId(){return questionId;}public Long fileAssetId(){return fileAssetId;}public String externalUrl(){return externalUrl;}}
